      return
    }

    // eslint-disable-next-line no-alert
    const result = window.confirm([title, message].filter(Boolean).join('\n'))

    if (result === true) {
      const confirm = buttons.find(({style}) => style !== 'cancel')
      confirm?.onPress?.()
      return
    }

    const cancel = buttons.find(({style}) => style === 'cancel')
