    match &s[..2] {
        "0b" => U256::from_bin_str(&s[2..]),
        "0o" => U256::from_oct_str(&s[2..]),
        "0x" => U256::from_hex_str(&s[2..]),
        _ => U256::from_dec_str(s),
    }
    .map_err(|e| e.to_string().into())
}

